IList<Student> studentList = new List<Student>() {
    new Student() { StudentID = 1, StudentName = "John", Age = 13 },
    new Student() { StudentID = 2, StudentName = "Moin", Age = 21 },
    new Student() { StudentID = 3, StudentName = "Bill", Age = 18 },
    new Student() { StudentID = 4, StudentName = "Ram", Age = 20 },
    new Student() { StudentID = 5, StudentName = "Ron", Age = 15 }
};

var filteredResult = from s in studentList
                     where s.Age > 12 && s.Age < 20
                     select s.StudentName;

// Result: John, Bill, Ron

public static bool IsTeenAger(Student stud)
{
    return stud.Age > 12 && stud.Age < 20;
}

// In query syntax
var filteredResult = from s in studentList
                     where IsTeenAger(s)
                     select s;

// In method syntax
var filteredResult = studentList.Where(IsTeenAger);

IList<Student> studentList = new List<Student>() {
    new Student() { StudentID = 1, StudentName = "John", Age = 18 },
    new Student() { StudentID = 2, StudentName = "Steve", Age = 15 },
    new Student() { StudentID = 3, StudentName = "Bill", Age = 25 },
    new Student() { StudentID = 4, StudentName = "Ram", Age = 20 },
    new Student() { StudentID = 5, StudentName = "Ron", Age = 19 }
};

var filteredResult = studentList.Where((s, i) => {
    if (i % 2 == 0) // if it is even element (index 0, 2, 4)
        return true;
    return false;
});

// Result: John, Bill, Ron (elements at index 0, 2, 4)

// Query syntax
var filteredResult = from s in studentList
                     where s.Age > 12
                     where s.Age < 20
                     select s;

// Method syntax
var filteredResult = studentList
    .Where(s => s.Age > 12)
    .Where(s => s.Age < 20);
